#!/usr/bin/env python3
"""
setupbot.py - Universal Antigravity & Linux Remote Control Bot
--------------------------------------------------------------
* Works everywhere:
  - Termux (Android mobile)
  - Native Linux Server / VPS (Ubuntu, Debian)
  - Cloud Containers (Docker, Render, Railway, Fly.io, Codespaces, Colab)
* 100% Non-Interactive / AI-Friendly:
  If TELEGRAM_BOT_TOKEN and TELEGRAM_ALLOWED_USER_ID are passed as env vars,
  it runs immediately without asking any questions!
* Docker / Free-Tier Friendly:
  Runs in foreground to keep containers alive, or background on VPS/Termux.
* Self-Healing:
  Built-in watchdog restarts the bot automatically on any crash or disconnect.
"""
import os
import subprocess
import sys
import time
import base64
import json

IS_WINDOWS = sys.platform == "win32"

BOT_CODE_B64 = b""

def is_termux():
    return "com.termux" in os.environ.get("PREFIX", "") or os.path.exists("/data/data/com.termux")

def is_container():
    return os.path.exists("/.dockerenv") or os.environ.get("CONTAINER") or os.environ.get("RENDER") or os.environ.get("RAILWAY_STATIC_URL")

def get_config():
    # 1. Bot Token
    token = os.environ.get("TELEGRAM_BOT_TOKEN", "").strip()
    token_file = os.path.join(os.path.expanduser("~"), "agy_bot", ".bot_token") if IS_WINDOWS else os.path.expanduser("~/.bot_token")

    saved_token = ""
    if not token and os.path.exists(token_file):
        with open(token_file, "r") as f:
            saved_token = f.read().strip()
        token = saved_token

    if token and sys.stdin.isatty():
        # Show saved token (masked) and ask to keep or change (15 sec timeout)
        masked = token[:8] + "..." + token[-4:] if len(token) > 12 else "****"
        print(f"• Saved Bot Token: {masked}")
        print("  [Auto-continuing in 15s] Type new token to change, or press Enter to keep: ", end="", flush=True)
        import threading as _thr2
        new_token_input = [None]
        def _read_token():
            try:
                new_token_input[0] = input().strip()
            except Exception:
                new_token_input[0] = ""
        t2 = _thr2.Thread(target=_read_token, daemon=True)
        t2.start()
        t2.join(timeout=15)
        new_input = new_token_input[0] if new_token_input[0] is not None else ""
        if new_input:
            token = new_input
            print("  ✅ Token updated!")
        else:
            print("\n  ✅ Keeping saved token.")

    if not token and sys.stdin.isatty():
        token = input("Enter Telegram Bot Token: ").strip()

    if not token:
        print("❌ Error: TELEGRAM_BOT_TOKEN is required! Set it via env var or file.")
        sys.exit(1)

    os.makedirs(os.path.dirname(token_file), exist_ok=True)
    with open(token_file, "w") as f:
        f.write(token)
    _private(token_file)

    # 2. Allowed Users (YOUR Telegram numeric ID - message @userinfobot to find it)
    env_users = os.environ.get("TELEGRAM_ALLOWED_USER_ID", "").strip()
    users_file = os.path.expanduser("~/.allowed_users")
    saved_users = ""
    if os.path.exists(users_file):
        try:
            with open(users_file, "r") as f:
                saved_users = f.read().strip()
        except Exception:
            saved_users = ""

    users = env_users or saved_users
    if not users and sys.stdin.isatty():
        print("• Telegram User ID not set. Open Telegram, message @userinfobot, and copy the number it shows.")
        users = input("Enter YOUR Telegram User ID (first ID = bot owner/admin): ").strip()
    if not users or not all(x.isdigit() for x in users.replace(",", " ").split()):
        print("❌ Error: a valid numeric TELEGRAM_ALLOWED_USER_ID is required (set env var or run interactively).")
        sys.exit(2)
    print(f"• Authorized Admin User ID: {users}")
    try:
        with open(users_file, "w") as f:
            f.write(users)
    except Exception:
        pass

    # 3. Tailscale Auth Key
    ts_key = os.environ.get("TAILSCALE_AUTHKEY", "").strip()
    ts_file = os.path.expanduser("~/.tailscale_authkey")
    if not ts_key and os.path.exists(ts_file):
        try:
            with open(ts_file, "r") as f:
                ts_key = f.read().strip()
        except Exception:
            pass
    if ts_key:
        print(f"• Tailscale Auth Key: [Configured]")
        try:
            with open(ts_file, "w") as f:
                f.write(ts_key)
        except Exception:
            pass
    else:
        print("• Tailscale Auth Key: [Not Set]")

    return token, users, ts_key

def _private(path):
    """chmod 600 on files that contain secrets (no-op on Windows)."""
    try:
        if not IS_WINDOWS:
            os.chmod(path, 0o600)
    except Exception:
        pass

def deploy_bot_file(target_path):
    os.makedirs(os.path.dirname(target_path), exist_ok=True)
    with open(target_path, "wb") as f:
        f.write(base64.b64decode(BOT_CODE_B64))
    os.chmod(target_path, 0o755)


def setup_tailscale_daemon(ts_key):
    if not ts_key:
        return
    import shutil
    print("🔑 Installing & Configuring Tailscale...")
    if not shutil.which("tailscale"):
        if is_termux():
            os.system("pkg install tailscale -y >/dev/null 2>&1 || true")
        elif os.path.exists("/usr/bin/apt-get") and os.geteuid() == 0:
            os.system("curl -fsSL https://tailscale.com/install.sh | sh >/dev/null 2>&1 || apt-get update && apt-get install -y tailscale >/dev/null 2>&1 || true")
        else:
            os.system("curl -fsSL https://tailscale.com/install.sh | sh >/dev/null 2>&1 || true")

    os.system("pkill -x tailscaled 2>/dev/null || true")
    time.sleep(1)

    if os.path.exists("/dev/net/tun"):
        os.system("nohup tailscaled --state=/var/lib/tailscale/tailscaled.state >/tmp/tailscaled.log 2>&1 &")
    else:
        os.system("nohup tailscaled --tun=userspace-networking --state=/tmp/tailscaled.state >/tmp/tailscaled.log 2>&1 &")
    time.sleep(3)

    print("Connecting Tailscale to Tailnet...")
    import shlex
    os.system(f"tailscale up --authkey={shlex.quote(ts_key)} --accept-routes --hostname=ag-remote-bot >/tmp/tailscale_up.log 2>&1")
    print("✅ Tailscale is live and running!")


def setup_windows(bot_token, allowed_users, ts_key):
    import shutil
    print("Detected: Windows Environment")
    home = os.path.expanduser("~")
    bot_dir = os.path.join(home, "agy_bot")
    workspace = os.path.join(home, "workspace")
    os.makedirs(bot_dir, exist_ok=True)
    os.makedirs(workspace, exist_ok=True)

    # Detect best available shell
    def detect_shell():
        wsl = shutil.which("wsl")
        if wsl:
            try:
                r = subprocess.run(["wsl", "--list", "--quiet"],
                    capture_output=True, text=True, timeout=5)
                distros = [l.strip().replace("\x00","") for l in r.stdout.splitlines()
                           if l.strip().replace("\x00","")]
                if distros:
                    print(f"✅ WSL detected! Distros: {', '.join(distros)}")
                    return "wsl", distros[0]
                print("✅ WSL detected (default distro)")
                return "wsl", None
            except Exception:
                return "wsl", None
        for p in [r"C:\Program Files\Git\bin\bash.exe",
                  r"C:\Program Files (x86)\Git\bin\bash.exe"]:
            if os.path.exists(p):
                print(f"✅ Git Bash detected: {p}")
                return "gitbash", p
        ps = shutil.which("powershell") or shutil.which("pwsh")
        if ps:
            print(f"✅ PowerShell detected: {ps}")
            return "powershell", ps
        print("⚠️  Using Windows CMD (basic mode)")
        return "cmd", "cmd.exe"

    shell_type, shell_path = detect_shell()

    # If WSL detected, ask user: WSL or native Windows? (15 sec timeout → WSL)
    if shell_type == "wsl":
        distros_str = shell_path or "default"
        print(f"\n{'='*50}")
        print(f"  🐧 WSL detected! Distro: {distros_str}")
        print(f"{'='*50}")
        print("\nRun bot inside WSL (better) or Windows native terminal?")
        print("  [W] WSL  (full Linux, recommended) ← default")
        print("  [N] Native Windows (CMD/PowerShell)")
        print("\nPress W or N then Enter. Auto-selecting WSL in 15 seconds...")
        print()

        import threading as _thr
        choice = [None]
        def _read_choice():
            try:
                c = input().strip().lower()
                choice[0] = c
            except Exception:
                choice[0] = "w"
        t = _thr.Thread(target=_read_choice, daemon=True)
        t.start()
        t.join(timeout=15)

        if choice[0] in ("n", "native", "no"):
            print("\n▶ Using Windows native terminal")
            shell_type = "cmd"
            shell_path = "cmd.exe"
            # Tell bot code to NOT use WSL even though it's detected
            os.environ["FORCE_WIN_NATIVE"] = "1"
        else:
            print(f"\n▶ Using WSL ({distros_str})")
            os.environ.pop("FORCE_WIN_NATIVE", None)
            # shell_type stays "wsl"

    # Deploy bot file
    bot_file = os.path.join(bot_dir, "telegram_bot.py")
    deploy_bot_file(bot_file)

    # Save token + allowed users
    token_save = os.path.join(bot_dir, ".bot_token")
    with open(token_save, "w") as f2:
        f2.write(bot_token)
    _private(token_save)

    u_file = os.path.join(bot_dir, "allowed_users.json")
    u_list = [x.strip() for x in allowed_users.replace(",", " ").split() if x.strip()]
    existing = []
    if os.path.isfile(u_file):
        try:
            with open(u_file, "r") as f2:
                existing = json.load(f2)
        except Exception:
            existing = []
    with open(u_file, "w") as f2:
        json.dump(sorted(list(set(existing + u_list))), f2, indent=2)

    # Build env
    env = os.environ.copy()
    env["TELEGRAM_BOT_TOKEN"] = bot_token
    env["TELEGRAM_ALLOWED_USER_ID"] = allowed_users
    if ts_key:
        env["TAILSCALE_AUTHKEY"] = ts_key

    # If WSL: copy bot inside WSL and run there (best experience - full Linux PTY)
    if shell_type == "wsl":
        distro_arg = ["-d", shell_path] if shell_path else []
        try:
            wsl_home_r = subprocess.run(
                ["wsl"] + distro_arg + ["--", "bash", "-c", "echo $HOME"],
                capture_output=True, text=True, timeout=5)
            wsl_home = wsl_home_r.stdout.strip()
        except Exception:
            wsl_home = "/root"

        wsl_bot = f"{wsl_home}/agy_bot/telegram_bot.py"
        with open(bot_file, "rb") as f2:
            bot_bytes = f2.read()

        subprocess.run(
            ["wsl"] + distro_arg + ["--", "bash", "-c",
             f"mkdir -p {wsl_home}/agy_bot {wsl_home}/workspace"],
            timeout=10)
        p = subprocess.Popen(
            ["wsl"] + distro_arg + ["--", "bash", "-c",
             f"cat > {wsl_bot}"],
            stdin=subprocess.PIPE)
        p.communicate(input=bot_bytes)
        subprocess.run(["wsl"] + distro_arg + ["--", "bash", "-c",
            f"chmod +x {wsl_bot}"])

        # Install agy inside WSL if not present
        agy_check = subprocess.run(
            ["wsl"] + distro_arg + ["--", "bash", "-c", "which agy || ls ~/.local/bin/agy 2>/dev/null"],
            capture_output=True, text=True)
        if not agy_check.stdout.strip():
            print("Installing agy CLI inside WSL...")
            subprocess.run(
                ["wsl"] + distro_arg + ["--", "bash", "-c",
                 "curl -fsSL https://antigravity.google/cli/install.sh | bash > /tmp/agy_install.log 2>&1"],
                timeout=120)

        print(f"\n🚀 Bot starting inside WSL ({shell_path or 'default'})...")
        print("Press Ctrl+C to stop.\n")

        wsl_env = f'export TELEGRAM_BOT_TOKEN="{bot_token}"; export TELEGRAM_ALLOWED_USER_ID="{allowed_users}"'
        # Watchdog loop
        while True:
            try:
                p = subprocess.Popen(
                    ["wsl"] + distro_arg + ["--", "bash", "-lc",
                     f"{wsl_env}; python3 {wsl_bot}"])
                p.wait()
                if p.returncode == 2:
                    print("❌ Bot refused to start (configuration error). Not restarting.")
                    break
                print("Bot exited. Restarting in 3s...")
            except KeyboardInterrupt:
                print("\nStopped.")
                break
            except Exception as ex:
                print(f"Error: {ex}. Restarting in 3s...")
            time.sleep(3)
        return

    # Native Windows needs pywinpty (ConPTY) for login + interactive terminals (hermes, python, ...)
    try:
        import winpty  # noqa: F401
    except ImportError:
        print("Installing pywinpty (needed for interactive terminal on native Windows)...")
        subprocess.run([sys.executable, "-m", "pip", "install", "pywinpty", "-q"])

    # No WSL - run bot directly in this same Python process (output visible)
    print(f"\n🚀 Bot starting in Windows native mode ({shell_type})...")
    print("Press Ctrl+C to stop.\n")

    # Set env vars so bot code picks them up
    os.environ["TELEGRAM_BOT_TOKEN"] = bot_token
    os.environ["TELEGRAM_ALLOWED_USER_ID"] = allowed_users
    if ts_key:
        os.environ["TAILSCALE_AUTHKEY"] = ts_key

    # Watchdog: run bot as separate subprocess (proper variable scope)
    while True:
        try:
            p = subprocess.Popen(
                [sys.executable, "-u", bot_file],
                env=env
            )
            p.wait()
            if p.returncode == 2:
                print("❌ Bot refused to start (configuration error, see message above). Not restarting.")
                break
            if p.returncode == 0:
                print("Bot exited cleanly. Restarting in 3s...")
            else:
                print(f"Bot exited (code {p.returncode}). Restarting in 3s...")
        except KeyboardInterrupt:
            print("\nStopped.")
            try: p.terminate()
            except Exception: pass
            break
        except Exception as ex:
            print(f"Error: {ex}. Restarting in 3s...")
        time.sleep(3)


def setup_native_linux(bot_token, allowed_users, ts_key):
    print("Detected: Native Linux / Docker / Cloud Environment")
    home = os.path.expanduser("~")
    bot_dir = os.path.join(home, "agy_bot")
    bin_dir = os.path.join(bot_dir, "bin")
    workspace = os.path.join(home, "workspace")
    os.makedirs(bin_dir, exist_ok=True)
    os.makedirs(workspace, exist_ok=True)

    # Install packages if root / apt available
    if os.path.exists("/usr/bin/apt-get") and os.geteuid() == 0:
        print("Installing essentials via apt-get...")
        os.system("apt-get update -y >/dev/null 2>&1 || true")
        os.system("apt-get install -y python3 python3-pip tmux curl wget git unzip tailscale >/dev/null 2>&1 || true")
    
    setup_tailscale_daemon(ts_key)

    # Install agy CLI if missing
    agy_bin = os.path.expanduser("~/.local/bin/agy")
    if not os.path.isfile(agy_bin):
        print("Installing Antigravity agy CLI...")
        os.system("curl -fsSL https://antigravity.google/cli/install.sh | bash >/dev/null 2>&1 || true")

    # Ensure persistent gemini config on cloud containers
    if os.path.isdir("/data") and not os.path.exists("/data/data"):
        data_gemini = "/data/.gemini"
        user_gemini = os.path.expanduser("~/.gemini")
        os.makedirs(data_gemini, exist_ok=True)
        if not os.path.islink(user_gemini):
            if os.path.exists(user_gemini):
                os.system(f"cp -r {user_gemini}/* {data_gemini}/ 2>/dev/null || true")
                os.system(f"rm -rf {user_gemini}")
            try:
                os.symlink(data_gemini, user_gemini)
            except Exception:
                pass

    # Browser stubs
    for stub in ["xdg-open", "termux-open", "termux-open-url"]:
        path = os.path.join(bin_dir, stub)
        with open(path, "w") as f:
            f.write("#!/bin/sh\nexit 0\n")
        os.chmod(path, 0o755)

    # Deploy bot script directly via python
    bot_file = os.path.join(bot_dir, "telegram_bot.py")
    deploy_bot_file(bot_file)

    # Environment
    env_content = f"""export TELEGRAM_BOT_TOKEN="{bot_token}"
export TELEGRAM_ALLOWED_USER_ID="{allowed_users}"
export TAILSCALE_AUTHKEY="{ts_key}"
export PATH="{bin_dir}:{home}/.local/bin:$PATH"
export BROWSER="/bin/true"
"""
    with open(os.path.join(bot_dir, ".env"), "w") as f:
        f.write(env_content)
    _private(os.path.join(bot_dir, ".env"))

    # Initial allowed users JSON
    u_file = os.path.join(bot_dir, "allowed_users.json")
    u_list = [x.strip() for x in allowed_users.replace(",", " ").split() if x.strip()]
    existing = []
    if os.path.isfile(u_file):
        try:
            with open(u_file, "r") as f:
                existing = json.load(f)
        except Exception:
            existing = []
    all_u = sorted(list(set(existing + u_list)))
    with open(u_file, "w") as f:
        json.dump(all_u, f, indent=2)

    # Kill any old bot process
    os.system("pkill -f 'telegram_bot.py' 2>/dev/null || true")
    time.sleep(1)

    # Execution mode
    run_foreground = is_container() or "--foreground" in sys.argv or not sys.stdin.isatty()

    if run_foreground:
        print("\n🚀 Starting Telegram Bot in FOREGROUND watchdog loop (Container/Cloud mode)...")
        print("Press Ctrl+C to stop.")
        while True:
            try:
                if ts_key:
                    os.environ["TAILSCALE_AUTHKEY"] = ts_key
                    os.system("pgrep -x tailscaled >/dev/null 2>&1 || (if [ -c /dev/net/tun ]; then nohup tailscaled --state=/var/lib/tailscale/tailscaled.state >/dev/null 2>&1 & else nohup tailscaled --tun=userspace-networking --state=/tmp/tailscaled.state >/dev/null 2>&1 & fi; sleep 2; tailscale up --authkey=\"$TAILSCALE_AUTHKEY\" --accept-routes --hostname=ag-remote-bot >/dev/null 2>&1 &)")
                env = os.environ.copy()
                env["TELEGRAM_BOT_TOKEN"] = bot_token
                env["TELEGRAM_ALLOWED_USER_ID"] = allowed_users
                env["TAILSCALE_AUTHKEY"] = ts_key
                env["PATH"] = f"{bin_dir}:{home}/.local/bin:" + env.get("PATH", "")
                env["BROWSER"] = "/bin/true"
                p = subprocess.Popen([sys.executable, bot_file], env=env)
                p.wait()
                if p.returncode == 2:
                    print("❌ Bot refused to start (configuration error). Not restarting.")
                    break
            except KeyboardInterrupt:
                print("\nStopping bot...")
                break
            except Exception as e:
                print(f"Bot exited: {e}. Restarting in 2s...")
            time.sleep(2)
    else:
        # VPS Background daemon
        start_script = os.path.join(bot_dir, "start.sh")
        with open(start_script, "w") as f:
            f.write(f"""#!/bin/bash
source {bot_dir}/.env
while true; do
    if [ -n "$TAILSCALE_AUTHKEY" ]; then
        if ! pgrep -x "tailscaled" >/dev/null 2>&1; then
            if [ -c /dev/net/tun ]; then
                nohup tailscaled --state=/var/lib/tailscale/tailscaled.state >/dev/null 2>&1 &
            else
                nohup tailscaled --tun=userspace-networking --state=/tmp/tailscaled.state >/dev/null 2>&1 &
            fi
            sleep 2
            tailscale up --authkey="$TAILSCALE_AUTHKEY" --accept-routes --hostname="ag-remote-bot" >/dev/null 2>&1 &
        fi
    fi
    python3 {bot_file} >> {bot_dir}/telegram_bot.log 2>&1
    sleep 2
done
""")
        os.chmod(start_script, 0o755)
        os.system(f"nohup bash {start_script} </dev/null >/dev/null 2>&1 &")
        print("\n✅ Bot started in background watchdog loop!")
        print(f"Logs: tail -f {bot_dir}/telegram_bot.log")

def setup_termux(bot_token, allowed_users, ts_key):
    print("Detected: Termux (Android) Environment")
    print("[1/5] Preparing Termux dependencies...")
    os.system("termux-wake-lock 2>/dev/null || true")
    os.system("pkg update -y && pkg install proot-distro tmux -y")

    print("[2/5] Installing Alpine Linux & gcompat (crash-proof fallback)...")
    os.system("proot-distro install alpine >/dev/null 2>&1 || true")
    os.system('proot-distro login alpine -- sh -c "apk update && apk add bash gcompat curl wget tmux python3 py3-pip" >/dev/null 2>&1 || true')

    print("[3/5] Installing PRoot Ubuntu & Deploying Bot...")
    os.system("proot-distro install ubuntu >/dev/null 2>&1 || true")
    # First deploy telegram_bot.py directly to ubuntu path
    ubuntu_bot_path = "/data/data/com.termux/files/usr/var/lib/proot-distro/containers/ubuntu/root/agy_bot/telegram_bot.py"
    try:
        deploy_bot_file(ubuntu_bot_path)
    except Exception:
        pass

    ubuntu_bash = f"""#!/bin/bash
set -e
export HOME=/root
cd /root

apt-get update -y >/dev/null 2>&1 || true
apt-get install -y python3 python3-pip tmux curl wget unzip >/dev/null 2>&1 || true

pkill -f "/usr/local/bin/ttyd" 2>/dev/null || true
nginx -s stop 2>/dev/null || true
pkill -f "nginx: master" 2>/dev/null || true
pkill -f "/root/agy_bot/url_watcher.py" 2>/dev/null || true
pkill -f "/root/agy_bot/telegram_bot.py" 2>/dev/null || true

if [ ! -f /root/.local/bin/agy ]; then
    echo "Installing Antigravity agy CLI..."
    curl -fsSL https://antigravity.google/cli/install.sh | bash >/dev/null 2>&1 || true
fi

mkdir -p /root/agy_bot /root/agy_bot/bin /root/workspace
cat << 'STUB_EOF' > /root/agy_bot/bin/xdg-open
#!/bin/sh
exit 0
STUB_EOF
cat << 'STUB_EOF' > /root/agy_bot/bin/termux-open
#!/bin/sh
exit 0
STUB_EOF
cat << 'STUB_EOF' > /root/agy_bot/bin/termux-open-url
#!/bin/sh
exit 0
STUB_EOF
chmod +x /root/agy_bot/bin/*

cd /root/agy_bot

cat << 'ENV_EOF' > .env
export TELEGRAM_BOT_TOKEN="{bot_token}"
export TELEGRAM_ALLOWED_USER_ID="{allowed_users}"
export TAILSCALE_AUTHKEY="{ts_key}"
export PATH="/root/agy_bot/bin:/root/.local/bin:$PATH"
export BROWSER="/bin/true"
ENV_EOF

python3 -c '
import os, json
ids = [x.strip() for x in "{allowed_users}".replace(",", " ").split() if x.strip()]
p = "/root/agy_bot/allowed_users.json"
existing = []
if os.path.isfile(p):
    try:
        with open(p, "r") as f:
            existing = json.load(f)
    except Exception:
        existing = []
all_users = sorted(list(set(existing + ids)))
with open(p, "w") as f:
    json.dump(all_users, f, indent=2)
'

cat << 'DAEMON_EOF' > start.sh
#!/bin/bash
source /root/agy_bot/.env
pkill -f "/root/agy_bot/telegram_bot.py" 2>/dev/null || true
sleep 1

echo "✅ Lightweight Telegram Bot watchdog started."
while true; do
    if [ -n "$TAILSCALE_AUTHKEY" ]; then
        if ! pgrep -x "tailscaled" >/dev/null 2>&1; then
            nohup tailscaled --tun=userspace-networking --state=/tmp/tailscaled.state >/dev/null 2>&1 &
            sleep 2
            tailscale up --authkey="$TAILSCALE_AUTHKEY" --accept-routes --hostname="ag-remote-bot" >/dev/null 2>&1 &
        fi
    fi
    python3 /root/agy_bot/telegram_bot.py >> /root/agy_bot/telegram_bot.log 2>&1
    sleep 2
done
DAEMON_EOF
chmod +x start.sh
"""
    process = subprocess.Popen(["proot-distro", "login", "ubuntu", "--", "bash"], stdin=subprocess.PIPE, text=True)
    process.communicate(ubuntu_bash)

    # Ensure bot file is deployed inside ubuntu
    ubuntu_bot_path = "/data/data/com.termux/files/usr/var/lib/proot-distro/containers/ubuntu/root/agy_bot/telegram_bot.py"
    try:
        deploy_bot_file(ubuntu_bot_path)
    except Exception:
        pass

    print("[3/4] Configuring Termux auto-boot...")
    termux_start = """#!/bin/bash
termux-wake-lock 2>/dev/null || true
if pgrep -f "telegram_bot.py" >/dev/null 2>&1; then
    exit 0
fi
pkill -f "/root/agy_bot/start.sh" 2>/dev/null || true
sleep 1
nohup proot-distro login ubuntu -- /root/agy_bot/start.sh </dev/null >/dev/null 2>&1 &
"""
    start_sh = os.path.expanduser("~/start_bot.sh")
    with open(start_sh, "w") as f:
        f.write(termux_start)
    os.system(f"chmod +x {start_sh}")

    boot_dir = os.path.expanduser("~/.termux/boot")
    os.makedirs(boot_dir, exist_ok=True)
    boot_script = os.path.join(boot_dir, "start_bot.sh")
    with open(boot_script, "w") as f:
        f.write("#!/bin/bash\ntermux-wake-lock 2>/dev/null || true\nbash ~/start_bot.sh\n")
    os.system(f"chmod +x {boot_script}")

    os.system("touch ~/.bashrc")
    os.system("grep -q 'start_bot.sh' ~/.bashrc || echo 'bash ~/start_bot.sh' >> ~/.bashrc")

    print("[4/4] Starting bot service...")
    os.system("pkill -9 -f '/root/agy_bot/start.sh' 2>/dev/null || true")
    os.system("pkill -9 -f 'telegram_bot.py' 2>/dev/null || true")
    os.system("bash ~/start_bot.sh")

